package tv.vela.launcher;

import android.content.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.*;

/** Local personalities and deliberately credential-free, versioned configuration snapshots. */
final class VelaWorkspace {
    static final int MAX_BYTES=512*1024,MAX_PROFILES=6;
    static final String DEFAULT="default";
    private VelaWorkspace(){}
    static SharedPreferences registry(Context c){return c.getSharedPreferences("vela-workspace",0);}
    static String active(Context c){String id=registry(c).getString("active",DEFAULT);return id.matches("[a-f0-9]{16}")&&profiles(c).containsKey(id)?id:DEFAULT;}
    static String physical(Context c,String name){String id=active(c);return DEFAULT.equals(id)?name:"vp-"+id+"-"+name;}
    static String channelSource(Context c,String source){if(!source.startsWith("xtream:"))return source;SharedPreferences account=c.getSharedPreferences("xtream",0);String portable=account.getString("portable-source","");return portable.matches("[a-f0-9]{64}")&&source.equals("xtream:"+account.getString("id",""))?"xtream:"+portable:source;}
    static synchronized SharedPreferences channelPrefs(Context c,String source){String portable=channelSource(c,source),name="tv-personal-"+LiveTvData.hash(portable);SharedPreferences target=prefs(c,name);if(!portable.equals(source)){String legacy="tv-personal-"+LiveTvData.hash(source);SharedPreferences old=prefs(c,legacy);if(!old.getAll().isEmpty()){SharedPreferences.Editor edit=target.edit();for(Map.Entry<String,?> e:old.getAll().entrySet())if(!target.contains(e.getKey())&&e.getValue() instanceof String)edit.putString(e.getKey(),(String)e.getValue());if(edit.commit()){old.edit().clear().commit();c.deleteSharedPreferences(physical(c,legacy));String key="names-"+active(c);Set<String> names=new HashSet<>(registry(c).getStringSet(key,Collections.emptySet()));names.remove(legacy);registry(c).edit().putStringSet(key,names).commit();}}}return target;}
    static SharedPreferences prefs(Context c,String name){if(name.matches("tv-personal-[a-f0-9]{64}")){String key="names-"+active(c);SharedPreferences registry=registry(c);Set<String> saved=new HashSet<>(registry.getStringSet(key,Collections.emptySet()));if(saved.size()<96&&saved.add(name))registry.edit().putStringSet(key,saved).commit();}return c.getSharedPreferences(physical(c,name),0);}
    static LinkedHashMap<String,String> profiles(Context c){LinkedHashMap<String,String> out=new LinkedHashMap<>();out.put(DEFAULT,t("Main","Principal"));try{JSONArray a=new JSONArray(registry(c).getString("profiles","[]"));for(int i=0;i<Math.min(a.length(),MAX_PROFILES-1);i++){JSONObject p=a.getJSONObject(i);String id=p.getString("id"),name=clean(p.getString("name"),32);if(id.matches("[a-f0-9]{16}")&&!name.isEmpty())out.put(id,name);}}catch(JSONException|ClassCastException ignored){}return out;}
    static synchronized String create(Context c,String name)throws IOException{LinkedHashMap<String,String> all=profiles(c);name=clean(name,32);if(name.isEmpty()||all.size()>=MAX_PROFILES)throw new IOException(t("Choose a name; at most six profiles.","Elige un nombre; máximo seis perfiles."));for(String n:all.values())if(normal(n).equals(normal(name)))throw new IOException(t("That name is already in use.","Ese nombre ya existe."));String id=UUID.randomUUID().toString().replace("-","").substring(0,16);all.put(id,name);saveProfiles(c,all);return id;}
    private static void saveProfiles(Context c,Map<String,String> all)throws IOException{JSONArray a=new JSONArray();try{for(Map.Entry<String,String> e:all.entrySet())if(!e.getKey().equals(DEFAULT))a.put(new JSONObject().put("id",e.getKey()).put("name",e.getValue()));if(!registry(c).edit().putString("profiles",a.toString()).commit())throw new IOException("Save failed");}catch(JSONException bad){throw new IOException(bad);}}
    static synchronized void select(Context c,String id)throws IOException{if(!profiles(c).containsKey(id)||!registry(c).edit().putString("active",id).commit())throw new IOException("Unknown profile");}
    static synchronized void delete(Context c,String id)throws IOException{if(DEFAULT.equals(id)||!profiles(c).containsKey(id))throw new IOException("Invalid profile");if(active(c).equals(id))select(c,DEFAULT);LinkedHashMap<String,String> all=profiles(c);all.remove(id);saveProfiles(c,all);File[] files=new File(c.getApplicationInfo().dataDir,"shared_prefs").listFiles();if(files!=null)for(File file:files)if(file.getName().startsWith("vp-"+id+"-")&&file.getName().endsWith(".xml")){String name=file.getName().substring(0,file.getName().length()-4);c.getSharedPreferences(name,0).edit().clear().commit();c.deleteSharedPreferences(name);}File undo=new File(c.getFilesDir(),"vela-undo-"+id+".json");undo.delete();new File(c.getFilesDir(),"vela-settings-"+id+".json").delete();registry(c).edit().remove("names-"+id).commit();SharedPreferences.Editor sync=VelaSync.prefs(c).edit();for(String key:VelaSync.prefs(c).getAll().keySet())if(key.startsWith(id+"-"))sync.remove(key);sync.commit();VelaConnect.privatePrefs(c).edit().remove("host-token-"+id).remove(id+"-peer").commit();}
    static String t(String en,String es){return Ui.tr(en,en,es);}
    static String clean(String s,int limit){if(s==null)return "";s=s.replaceAll("[\\p{Cntrl}]"," ").trim();return s.substring(0,Math.min(limit,s.length()));}
    static String normal(String s){return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).trim();}
    private static void depth(String text)throws IOException{int level=0;boolean quoted=false,escaped=false,done=false;for(int i=0;i<text.length();i++){char ch=text.charAt(i);if(quoted){if(escaped)escaped=false;else if(ch=='\\')escaped=true;else if(ch=='"')quoted=false;continue;}if(i==0&&ch=='\uFEFF')continue;if(done&&!Character.isWhitespace(ch))throw new IOException("Trailing backup content");if(ch=='"')quoted=true;else if(ch=='{'||ch=='['){if(++level>8)throw new IOException("Backup nesting limit");}else if(ch=='}'||ch==']'){if(--level<0)throw new IOException("Invalid backup structure");if(level==0)done=true;}}if(level!=0||quoted)throw new IOException("Incomplete backup");}
    private static boolean namespace(String n){return Arrays.asList("visuals","sidebar_apps","input_cards","lite_home","lite_tv","vela-reading","vela-programmes","vela-remote","live-tv","vela-layout","vela-epg-fixes").contains(n)||n.matches("tv-personal-[a-f0-9]{64}");}
    private static boolean allowed(String n,String k){
        if(n.equals("vela-layout"))return k.equals("document");
        if(n.equals("vela-epg-fixes"))return k.equals("entries");
        if(n.equals("visuals"))return k.matches("appearance_(color|size|backdrop|style)")||Arrays.asList("light","reducedMotion").contains(k);
        if(n.equals("sidebar_apps"))return k.equals("slots");
        if(n.equals("input_cards"))return k.matches("device_[a-f0-9]{64}");
        if(n.equals("lite_home"))return Arrays.asList("black_background","show_clock","reduce_motion","start_section").contains(k);
        if(n.equals("lite_tv"))return Arrays.asList("favourites","channel_view","online_guide").contains(k);
        if(n.equals("live-tv"))return k.matches("favorites-[a-f0-9]{64}");
        if(n.startsWith("tv-personal-"))return Arrays.asList("hidden","groups","order").contains(k);
        if(n.equals("vela-reading"))return Arrays.asList("text","density","margin","contrast").contains(k);
        if(n.equals("vela-remote"))return Arrays.asList("search_key","voice_key","profiles_key","bindings").contains(k);
        return n.equals("vela-programmes")&&k.equals("rules");
    }
    private static Object encode(Object v)throws JSONException{if(v instanceof Set)return new JSONArray(new TreeSet<>((Set<String>)v));return v;}
    private static Object validate(String n,String k,Object v)throws IOException,JSONException{
        if(!allowed(n,k))throw new IOException("Unexpected configuration field");
        boolean set=n.equals("live-tv")||n.equals("lite_tv")&&k.equals("favourites");
        boolean string=n.equals("vela-remote")&&k.equals("bindings")||n.equals("vela-layout")||n.equals("vela-epg-fixes")||n.equals("sidebar_apps")||n.equals("input_cards")||n.startsWith("tv-personal-")||n.equals("vela-programmes");
        boolean integer=n.equals("visuals")&&k.startsWith("appearance_")||n.equals("lite_home")&&k.equals("start_section")||n.equals("vela-reading")&&!k.equals("contrast")||n.equals("vela-remote")&&!k.equals("bindings");
        if(set&&!(v instanceof JSONArray)||string&&!(v instanceof String)||integer&&!(v instanceof Integer)||!set&&!string&&!integer&&!(v instanceof Boolean))throw new IOException("Wrong setting type");
        if(v instanceof String){String s=(String)v;if(s.length()>96*1024||s.matches("(?is).*https?://.*"))throw new IOException("Invalid configuration value");if(n.equals("vela-remote")){if(s.length()>8192)throw new IOException("Shortcuts too large");depth(s);VelaRemote.validate(new JSONArray(s));}if(n.equals("vela-layout")||n.equals("vela-epg-fixes")){depth(s);try{if(n.equals("vela-layout"))VelaLayout.validate(new JSONObject(s));else VelaGuideFix.validate(new JSONObject(s));}catch(Exception bad){throw new IOException("Invalid layout or guide correction",bad);}}if(n.equals("sidebar_apps")){depth(s);JSONArray a=new JSONArray(s);if(a.length()>128)throw new IOException("Too many shortcuts");for(int i=0;i<a.length();i++)if(!a.getString(i).matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+"))throw new IOException("Invalid app");}if(n.equals("input_cards")&&!Arrays.asList(TvInputs.PRESETS).contains(s))throw new IOException("Invalid input profile");if(n.startsWith("tv-personal-")||n.equals("vela-programmes")){depth(s);JSONArray a=new JSONArray(s);if(a.length()>512)throw new IOException("Too many entries");}return s;}
        if(v instanceof Boolean)return v;
        if(v instanceof Number){int i=((Number)v).intValue();if(i<0||i>512)throw new IOException("Invalid setting");if(n.equals("visuals")&&i>(k.equals("appearance_color")?5:2)||n.equals("lite_home")&&i>2||n.equals("vela-reading")&&i>(k.equals("margin")?3:2))throw new IOException("Invalid reading setting");if(n.equals("vela-remote")&&!VelaRemote.allowed(i))throw new IOException("Reserved key");return i;}
        if(v instanceof JSONArray){JSONArray a=(JSONArray)v;if(a.length()>(n.equals("live-tv")?128:256))throw new IOException("Too many favourites");Set<String> out=new LinkedHashSet<>();for(int i=0;i<a.length();i++){String s=a.getString(i);if(s.length()>256||s.contains("://")||s.matches(".*[\\p{Cntrl}].*"))throw new IOException("Invalid identifier");out.add(s);}return out;}
        throw new IOException("Invalid value type");
    }
    static synchronized JSONObject snapshot(Context c)throws IOException{
        JSONObject data=new JSONObject();Set<String> names=new TreeSet<>(Arrays.asList("visuals","sidebar_apps","input_cards","lite_home","lite_tv","vela-reading","vela-programmes","vela-remote","live-tv","vela-layout","vela-epg-fixes"));String prefix=active(c).equals(DEFAULT)?"":"vp-"+active(c)+"-";
        names.addAll(registry(c).getStringSet("names-"+active(c),Collections.emptySet()));File[] files=new File(c.getApplicationInfo().dataDir,"shared_prefs").listFiles();if(files!=null)for(File f:files){String n=f.getName();if(n.startsWith(prefix+"tv-personal-")&&n.endsWith(".xml"))names.add(n.substring(prefix.length(),n.length()-4));}
        try{int total=0;for(String n:names){if(!namespace(n)||++total>96)continue;JSONObject values=new JSONObject();for(Map.Entry<String,?> e:prefs(c,n).getAll().entrySet())if(allowed(n,e.getKey())){Object encoded=encode(e.getValue());validate(n,e.getKey(),encoded);values.put(e.getKey(),encoded);}if(values.length()>0)data.put(n,values);}JSONObject root=new JSONObject().put("format","vela-settings").put("version",1).put("edition",c.getPackageName().endsWith(".lite")?"lite":"full").put("created",System.currentTimeMillis()).put("settings",data);VelaAntennaBackup.describe(c,root);return root;}catch(JSONException e){throw new IOException("Invalid settings",e);}
    }
    static JSONObject read(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(out.size()+n>MAX_BYTES)throw new IOException(t("Backup too large.","La copia es demasiado grande."));out.write(b,0,n);}try{String text=out.toString("UTF-8");depth(text);JSONObject j=new JSONObject(text);validateSnapshot(j);return j;}catch(JSONException e){throw new IOException(t("This is not a Vela settings backup.","No es una copia de ajustes de Vela."),e);}}
    private static JSONObject validateSnapshot(JSONObject j)throws IOException,JSONException{if(j.length()>6)throw new IOException("Unknown backup metadata");for(Iterator<String> fields=j.keys();fields.hasNext();)if(!Arrays.asList("format","version","edition","created","settings","antenna").contains(fields.next()))throw new IOException("Unknown backup metadata");if(!(j.get("version") instanceof Integer)||j.has("created")&&!(j.get("created") instanceof Number)||j.has("antenna")&&(!(j.get("antenna") instanceof JSONObject)||j.getJSONObject("antenna").length()>512))throw new IOException("Invalid backup metadata");if(!j.optString("format").equals("vela-settings")||j.optInt("version")!=1||!Arrays.asList("lite","full").contains(j.optString("edition")))throw new IOException("Unsupported backup");JSONObject data=j.getJSONObject("settings");if(data.length()>96)throw new IOException("Too many sections");for(Iterator<String> it=data.keys();it.hasNext();){String n=it.next();if(!namespace(n))throw new IOException("Unknown section");JSONObject values=data.getJSONObject(n);if(values.length()>768)throw new IOException("Too many settings");for(Iterator<String> keys=values.keys();keys.hasNext();){String k=keys.next();validate(n,k,values.get(k));}}return data;}
    static String description(JSONObject j){JSONObject d=j.optJSONObject("settings");return (d==null?0:d.length())+t(" setting groups · "," grupos de ajustes · ")+(j.optString("edition").equals("lite")?"Vela Lite":"Vela")+"\n"+t("Applied to the active profile. Accounts and passwords are not included.","Se aplicará al perfil activo. No incluye cuentas ni contraseñas.");}
    static void write(JSONObject j,OutputStream out)throws IOException{byte[] bytes=j.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>MAX_BYTES)throw new IOException("Backup too large");out.write(bytes);out.flush();}
    private static File undoFile(Context c){return new File(c.getFilesDir(),"vela-undo-"+active(c)+".json");}
    static synchronized void saveUndo(Context c)throws IOException{File temp=new File(c.getFilesDir(),"vela-undo.tmp");try(FileOutputStream out=new FileOutputStream(temp)){write(snapshot(c),out);out.getFD().sync();}if(!temp.renameTo(undoFile(c))){temp.delete();throw new IOException("Could not save recovery copy");}}
    static boolean canUndo(Context c){return undoFile(c).isFile();}
    static void undo(Context c)throws IOException{JSONObject before;try(InputStream in=new FileInputStream(undoFile(c))){before=read(in);}apply(c,before,false);}
    private static void put(SharedPreferences.Editor e,String k,Object v){if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else e.putStringSet(k,(Set<String>)v);}
    static synchronized void apply(Context c,JSONObject j,boolean save)throws IOException{
        Map<String,SharedPreferences> destinations=new LinkedHashMap<>();Map<String,Map<String,?>> previous=new LinkedHashMap<>();
        try{
            validateSnapshot(j);JSONObject old=snapshot(c).getJSONObject("settings"),data=VelaAntennaBackup.prepare(c,j,old);boolean same=j.getString("edition").equals(c.getPackageName().endsWith(".lite")?"lite":"full");Set<String> names=new TreeSet<>();for(Iterator<String> it=old.keys();it.hasNext();)names.add(it.next());for(Iterator<String> it=data.keys();it.hasNext();)names.add(it.next());
            for(String n:names){if(!same&&!n.equals("vela-reading")&&!n.equals("input_cards")&&!n.equals("vela-remote")&&!n.equals("vela-layout"))continue;SharedPreferences p=prefs(c,n);destinations.put(n,p);previous.put(n,new HashMap<>(p.getAll()));}
            if(save)saveUndo(c);
            for(Map.Entry<String,SharedPreferences> entry:destinations.entrySet()){
                if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();String n=entry.getKey();SharedPreferences.Editor edit=entry.getValue().edit();for(String k:previous.get(n).keySet())if(allowed(n,k))edit.remove(k);JSONObject values=data.optJSONObject(n);if(values!=null)for(Iterator<String> keys=values.keys();keys.hasNext();){String k=keys.next();put(edit,k,validate(n,k,values.get(k)));}if(!edit.commit())throw new IOException("Write failed");
            }
            if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();registry(c).edit().putLong("revision",System.nanoTime()).commit();VelaShows.cancel(c);VelaShows.prefs(c).edit().remove("airings").remove("scan").remove("shown").commit();VelaShows.schedule(c);
        }catch(JSONException|RuntimeException|IOException failure){
            for(Map.Entry<String,SharedPreferences> entry:destinations.entrySet()){String n=entry.getKey();SharedPreferences.Editor edit=entry.getValue().edit();for(String k:entry.getValue().getAll().keySet())if(allowed(n,k))edit.remove(k);for(Map.Entry<String,?> before:previous.get(n).entrySet())if(allowed(n,before.getKey()))put(edit,before.getKey(),before.getValue());edit.commit();}
            throw new IOException(t("Restore failed; previous settings recovered.","No se pudo restaurar; se han recuperado los ajustes anteriores."),failure);
        }
    }
}
